'use client';
import { useEffect, useMemo, useState } from 'react';
import VendorShell from '../../components/VendorShell';
import { api } from '../../lib/api';

type Row = { id:string; quantity:number; lowStockThreshold:number; updatedAt:string; product?:{id:string;name:string;sku?:string|null;unit?:string|null;isAvailable:boolean;vendorCategory?:{id:string;name:string}|null}; variant?:{id:string;name:string;productId:string}|null };
const moneyless = (n:number) => n.toLocaleString('en-NG');

export default function InventoryPage(){
 const [rows,setRows]=useState<Row[]>([]),[q,setQ]=useState(''),[status,setStatus]=useState('all'),[loading,setLoading]=useState(true),[error,setError]=useState(''),[success,setSuccess]=useState('');
 const [selected,setSelected]=useState<Row|null>(null),[delta,setDelta]=useState(''),[reason,setReason]=useState(''),[threshold,setThreshold]=useState('');
 async function load(){try{setLoading(true);setError('');const data=await api<Row[]>(`/api/vendor/inventory${status==='all'?'':`?status=${status}`}`);setRows(data)}catch(e:any){setError(e?.message||'Failed to load inventory.')}finally{setLoading(false)}}
 useEffect(()=>{load()},[status]);
 const filtered=useMemo(()=>rows.filter(r=>{const text=`${r.product?.name||''} ${r.variant?.name||''} ${r.product?.sku||''}`.toLowerCase();return text.includes(q.toLowerCase())}),[rows,q]);
 const stats={total:rows.length,units:rows.reduce((s,r)=>s+r.quantity,0),low:rows.filter(r=>r.quantity>0&&r.quantity<=r.lowStockThreshold).length,out:rows.filter(r=>r.quantity===0).length};
 function open(r:Row){setSelected(r);setDelta('');setReason('');setThreshold(String(r.lowStockThreshold))}
 async function adjust(){if(!selected)return;try{setError('');setSuccess('');const n=Number(delta);if(!Number.isInteger(n)||n===0)throw Error('Enter a non-zero whole-number adjustment.');if(!reason.trim())throw Error('Enter a reason for the stock adjustment.');await api(`/api/vendor/inventory/${selected.id}/adjust`,{method:'PATCH',body:JSON.stringify({quantityDelta:n,reason:reason.trim()})});setSuccess('Stock updated successfully.');setSelected(null);await load()}catch(e:any){setError(e?.message||'Could not update stock.')}}
 async function saveThreshold(){if(!selected)return;try{const n=Number(threshold);if(!Number.isInteger(n)||n<0)throw Error('Threshold must be 0 or more.');await api(`/api/vendor/inventory/${selected.id}/threshold`,{method:'PATCH',body:JSON.stringify({lowStockThreshold:n})});setSuccess('Low-stock threshold updated.');setSelected(null);await load()}catch(e:any){setError(e?.message||'Could not update threshold.')}}
 return <VendorShell><main className="page-content"><div className="page-heading"><div><div className="eyebrow">CATALOG / STOCK</div><h1>Inventory</h1><p className="muted">Control stock quantities, thresholds and the history behind every manual adjustment.</p></div><button className="btn secondary" onClick={load}>Refresh</button></div>{error&&<div className="alert error">{error}</div>}{success&&<div className="alert success">{success}</div>}
 <div className="metric-grid"><div className="metric-card"><span>Inventory items</span><strong>{stats.total}</strong><small>Products + variants</small></div><div className="metric-card"><span>Total units</span><strong>{moneyless(stats.units)}</strong><small>Current sellable stock</small></div><div className="metric-card"><span>Low stock</span><strong>{stats.low}</strong><small>At or below threshold</small></div><div className="metric-card"><span>Out of stock</span><strong>{stats.out}</strong><small>Quantity is zero</small></div></div>
 <section className="content-card"><div className="toolbar"><input className="input search-input" value={q} onChange={e=>setQ(e.target.value)} placeholder="Search products, variants or SKU..."/><select className="input filter-select" value={status} onChange={e=>setStatus(e.target.value)}><option value="all">All stock</option><option value="low">Low stock</option><option value="out">Out of stock</option><option value="healthy">Healthy stock</option></select></div>{loading?<div className="state-panel"><h3>Loading inventory…</h3></div>:!filtered.length?<div className="state-panel"><div className="state-icon">▤</div><h3>{rows.length?'No inventory matches your filters':'No inventory yet'}</h3><p className="muted">Inventory records are created automatically when products or variants are created.</p></div>:<div className="table-wrap"><table className="data-table"><thead><tr><th>Item</th><th>Category</th><th>Stock</th><th>Threshold</th><th>Availability</th><th>Updated</th><th></th></tr></thead><tbody>{filtered.map(r=>{const low=r.quantity>0&&r.quantity<=r.lowStockThreshold;return <tr key={r.id}><td><div className="table-primary">{r.product?.name||'Product'}{r.variant&&<span className="table-secondary"> · {r.variant.name}</span>}</div><div className="table-secondary">{r.product?.sku||'No SKU'}{r.product?.unit?` · ${r.product.unit}`:''}</div></td><td>{r.product?.vendorCategory?.name||'—'}</td><td><span className={`status-badge ${r.quantity===0?'status-danger':low?'status-warning':'status-active'}`}>{r.quantity===0?'Out of stock':`${moneyless(r.quantity)} in stock`}</span></td><td>{r.lowStockThreshold}</td><td>{r.product?.isAvailable?'Available':'Hidden'}</td><td>{new Date(r.updatedAt).toLocaleString()}</td><td><button className="text-button" onClick={()=>open(r)}>Manage</button></td></tr>})}</tbody></table></div>}</section>
 <div className="info-banner"><strong>Inventory rule</strong><span>Positive adjustments add stock; negative adjustments deduct it. ROZZI blocks negative quantities and records the before/after quantity, reason and actor in an immutable movement history.</span></div>
 {selected&&<div className="drawer-backdrop" onMouseDown={e=>e.currentTarget===e.target&&setSelected(null)}><aside className="side-drawer"><div className="drawer-header"><div><div className="eyebrow">INVENTORY CONTROL</div><h2>{selected.product?.name}{selected.variant?` · ${selected.variant.name}`:''}</h2></div><button className="drawer-close" onClick={()=>setSelected(null)}>×</button></div><div className="drawer-body"><div className="inventory-hero"><span>Current stock</span><strong>{moneyless(selected.quantity)}</strong><small>{selected.product?.unit||'units'}</small></div><label>Stock adjustment<input className="input" type="number" step="1" value={delta} onChange={e=>setDelta(e.target.value)} placeholder="+10 to add, -2 to deduct"/></label><label>Reason<input className="input" value={reason} onChange={e=>setReason(e.target.value)} placeholder="e.g. Restock delivery, damaged stock"/></label><button className="btn primary full" onClick={adjust}>Apply adjustment</button><hr/><label>Low-stock threshold<input className="input" type="number" min="0" value={threshold} onChange={e=>setThreshold(e.target.value)}/></label><button className="btn secondary full" onClick={saveThreshold}>Save threshold</button><div className="drawer-note"><strong>Stock history</strong><p>Every manual adjustment is recorded with the previous quantity, new quantity, reason and responsible vendor user. Order deductions can use the same inventory record without allowing negative stock.</p></div></div></aside></div>}</main></VendorShell>
}
